package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
import java.util.*;

final class EmployeeOnboardingBrowserAcceptance {
 static void add(Page p,String group,String title,String summary,String details){p.getByLabel("Employee display title").fill(title);p.getByLabel("Department summary").fill(summary);p.getByLabel("Department instructions").fill(details);p.getByLabel("Responsible department").selectOption(group);p.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Add onboarding step")).press("Enter");}
 static void finish(Page p,String outcome){p.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Claim task").setExact(true)).press("Enter");p.getByLabel("Completion outcome").fill(outcome);p.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Complete task").setExact(true)).press("Enter");}
 static void run(BrowserTest h)throws Exception{
  String parent,it,fac;
  try(var db=h.store.open()){PlatformFoundationTest.bind(db);for(String name:List.of("OnboardBrowserEmployee","OnboardBrowserHR","OnboardBrowserIT","OnboardBrowserFacilities"))Service.createAccount(db,map("name",name,"role","agent","password",WorkflowSupport.PASSWORD));String hr=Service.create(db,"sys_user_group",map("short_description","Onboarding HR team"),"admin").get("sys_id").toString();it=Service.create(db,"sys_user_group",map("short_description","Onboarding IT team"),"admin").get("sys_id").toString();fac=Service.create(db,"sys_user_group",map("short_description","Onboarding facilities team"),"admin").get("sys_id").toString();for(var entry:Map.of(hr,"OnboardBrowserHR",it,"OnboardBrowserIT",fac,"OnboardBrowserFacilities").entrySet())db.update("INSERT INTO os_group_member(group_id,user_id) VALUES(?,?)",entry.getKey(),RecordAccess.owner(db,entry.getValue()));EmployeeServices.save(db,map("operation","employee","username","OnboardBrowserEmployee","department","Engineering","active",true,"revision",0));var body=EmployeeCasesAcceptance.service("",0,hr,"Engineering");body.put("name","Onboarding browser service");EmployeeServices.save(db,body);String service=db.one("SELECT service_id FROM os_hr_service WHERE name='Onboarding browser service'").get("service_id").toString();db.viewerId=RecordAccess.owner(db,"OnboardBrowserEmployee");db.viewerRole="agent";parent=EmployeeCases.create(db,service,map("employee_revision",1,"service_revision",1,"summary","Welcome to your new role","description","PRIVATE HR onboarding details","key",Values.id())).get("sys_id").toString();db.connection.commit();}
  try(var playwright=Playwright.create();var browser=playwright.chromium().launch();var hc=browser.newContext();var ic=browser.newContext();var fc=browser.newContext();var ec=browser.newContext()){
   var hr=hc.newPage();h.login(hr,"OnboardBrowserHR");hr.navigate(h.base()+"/record/hr_case/"+parent);hr.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Plan employee onboarding")).press("Enter");add(hr,it,"Your equipment <script>","Prepare onboarding laptop","DEPARTMENT IT instructions");add(hr,fac,"Your workspace","Prepare onboarding workspace","DEPARTMENT facilities instructions");add(hr,fac,"Remove this draft","Draft for removal","Do not launch this work");hr.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Remove step Remove this draft").setExact(true)).press("Enter");assertThat(hr.getByText("Do not launch this work")).hasCount(0);ReleaseBrowserAcceptance.accessible(hr);hr.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/onboarding-plan-light.png")).setFullPage(true));hr.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Launch reviewed onboarding")).press("Enter");assertThat(hr.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Add onboarding step"))).hasCount(0);
   var facilities=fc.newPage();h.login(facilities,"OnboardBrowserFacilities");facilities.navigate(h.base()+"/work-tasks");facilities.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Prepare onboarding workspace")).press("Enter");assertThat(facilities.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Claim task"))).hasCount(0);assertThat(facilities.locator("main")).containsText("Waiting for predecessor");
   var tech=ic.newPage();h.login(tech,"OnboardBrowserIT");tech.navigate(h.base()+"/work-tasks");tech.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Prepare onboarding laptop")).press("Enter");assertThat(tech.locator("main")).not().containsText("PRIVATE HR");for(String button:List.of("Cancel task","Create work task","Save completion gate"))assertThat(tech.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName(button).setExact(true))).hasCount(0);ReleaseBrowserAcceptance.accessible(tech);tech.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/onboarding-department-light.png")).setFullPage(true));finish(tech,"DEPARTMENT IT verification receipt");facilities.reload();finish(facilities,"DEPARTMENT facilities verification receipt");
   var employee=ec.newPage();h.login(employee,"OnboardBrowserEmployee");employee.navigate(h.base()+"/employee-service/cases/"+parent);assertThat(employee.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Your onboarding progress"))).hasCount(1);assertThat(employee.locator("main")).containsText("Your equipment <script>");assertThat(employee.locator("main")).not().containsText("DEPARTMENT");assertThat(employee.locator("main script")).hasCount(0);assertThat(employee.getByText("complete",new Page.GetByTextOptions().setExact(true))).hasCount(2);employee.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Dark mode").setExact(true)).press("Enter");employee.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(employee);assertEquals(false,employee.evaluate("document.documentElement.scrollWidth>window.innerWidth"));employee.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/onboarding-employee-dark.png")).setFullPage(true));hr.reload();assertThat(hr.locator("main")).not().containsText("verification receipt");hr.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("HR case workspace")).press("Enter");hr.locator("select[name=state]").selectOption("working");hr.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save changes →")).press("Enter");hr.locator("select[name=state]").selectOption("closed");hr.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save changes →")).press("Enter");employee.reload();assertThat(employee.locator("main")).containsText("Closed complete");
  }
 }
}
